package net.battlespades.bot;
import java.io.*;
import java.math.BigInteger;
import java.util.*;
import java.util.zip.InflaterInputStream;
import net.battlespades.physics.PlayerPhysics.Vector;
import static net.battlespades.bot.BotState.*;
import net.battlespades.bot.BotState.Observer;
import static net.battlespades.bot.BotFoundationsTest.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class BotNavigationTest {
    static byte[] raw(Object value)throws IOException{byte[] compressed=Base64.getDecoder().decode(string(value));try(var in=new InflaterInputStream(new ByteArrayInputStream(compressed))){return in.readAllBytes();}}
    @Test void compactCollisionMatchesOriginalClassicMarkersImplicitGroundAndRetainedInput()throws Exception{for(var value:list(FIXTURE.get("compact"))){var row=map(value);byte[] raw=raw(row.get("raw_zlib"));var collision=new CompactVoxelMap(raw,string(row.get("format")));assertEquals(integer(row.get("shift")),collision.sourceZShift());Arrays.fill(raw,(byte)0);for(var v:list(row.get("probes"))){var p=list(v);assertEquals(bool(p.get(3)),collision.solid(integer(p.get(0)),integer(p.get(1)),integer(p.get(2))));}for(var v:list(row.get("columns"))){var c=map(v);int x=integer(c.get("x")),y=integer(c.get("y"));assertEquals(integer(c.get("surface")),collision.surfaceZ(x,y));var mask=new BigInteger(string(c.get("mask")).substring(2),16);for(int word=0;word<4;word++)assertEquals(mask.shiftRight(word*64).longValue(),collision.word(y*512+x,word));}}for(byte[] invalid:List.of(new byte[0],new byte[]{0,1},new byte[]{0,(byte)240,(byte)255,0},new byte[]{(byte)255,0,0,0}))assertThrows(IllegalArgumentException.class,()->new CompactVoxelMap(invalid,"retail"));}
    @Test void originalSnapshotDeltasLayeredCorridorsAndBodyWideFollowingRemainConnected()throws Exception{var row=map(FIXTURE.get("world"));var world=new BotNavigationWorld();world.load(new MapSnapshot(7,10,raw(row.get("raw_zlib")),"tdm","",List.of(),"retail"));var route=list(row.get("route")).stream().map(v->{var s=map(v);return new RouteStep(vector(s.get("waypoint")),Affordance.valueOf(string(s.get("affordance")).toUpperCase(Locale.ROOT)));}).toList();for(var value:list(row.get("commands"))){var c=map(value);var expected=map(c.get("result"));if(c.get("op").equals("delta")){var cells=list(c.get("cells")).stream().map(v->{var a=list(v);return new VoxelChange(integer(a.get(0)),integer(a.get(1)),integer(a.get(2)),bool(a.get(3)),integer(a.get(4)),real(a.get(5)));}).toList();world.apply(new WorldDelta(7,number(c.get("version")),cells));assertEquals(number(expected.get("version")),world.version());equal(expected.get("health"),world.blockHealth(250,245,97));continue;}var at=vector(c.get("at"));var goal=vector(c.get("goal"));equal(expected.get("surface"),world.surface((int)at.x(),(int)at.y(),at.z(),4,false));equal(expected.get("goal"),world.goalSurface(goal,false));equal(expected.get("sight"),world.lineOfSight(at,goal));equal(expected.get("supports"),world.supports((int)at.x(),(int)at.y(),false));var corridor=world.corridor(at,goal,Set.of());var slices=new ArrayList<Integer>();if(corridor!=null)while(!corridor.done()){corridor.advance();slices.add(corridor.expansions());assertTrue(slices.size()<=65);}equal(expected.get("slices"),slices);equal(expected.get("path"),corridor==null?List.of():corridor.path());equal(expected.get("replan"),List.of(world.needsReplan(10,at,route,false),world.needsReplan(world.version(),at,route,false),world.needsReplan(10,at,route,true)));equal(expected.get("walk"),PathFollowing.straightWalkable(world,at,goal));equal(expected.get("lookahead"),PathFollowing.lookahead(world,route,0,at,null));equal(expected.get("run_end"),PathFollowing.runEnd(route,0));equal(expected.get("gaze"),PathFollowing.gazeWaypoint(route,0,at));equal(expected.get("remaining"),PathFollowing.remainingDistance(route,0,at));}long previous=world.version();world.apply(new WorldDelta(999,999,List.of(new VoxelChange(245,245,97,true,0,9))));assertEquals(previous,world.version());world.apply(new WorldDelta(7,9,List.of(new VoxelChange(245,245,97,true,0,9))));assertEquals(previous,world.version());for(var value:list(FIXTURE.get("following"))){var f=map(value);var edge=list(f.get("edge"));var step=new RouteStep(new Vector(0,0,0),Affordance.JUMP,null,new Edge(cell(edge.get(0)),cell(edge.get(1))));equal(f.get("axis"),PathFollowing.edgeAxis(step));equal(f.get("alignment"),PathFollowing.takeoffAlignment(step,vector(f.get("position"))));}}
    @Test void changedFarawayTerrainKeepsGuidanceWhileStuckExactEdgesReconsiderAndWorkerCreditDefers()throws Exception{var row=map(FIXTURE.get("world"));var budget=new PlanningBudget(1,8);var world=new BotNavigationWorld(budget,()->0);byte[] source=raw(row.get("raw_zlib"));var snapshot=new MapSnapshot(7,10,source,"tdm","",List.of(),"retail");source[0]=0;byte[] leak=snapshot.rawVxl();leak[0]=0;world.load(snapshot.rebase(10,List.of()));var at=new Vector(245.5,245.5,97.75);var route=List.of(new RouteStep(new Vector(260.5,245.5,97.75),Affordance.WALK));world.apply(new WorldDelta(7,11,List.of(new VoxelChange(400,400,40,true,0,9))));assertFalse(world.needsReplan(10,at,route,false));world.apply(new WorldDelta(7,12,List.of(new VoxelChange(252,246,90,true,0,9))));assertTrue(world.needsReplan(10,at,route,false));assertFalse(world.needsReplan(12,at,route,false));assertTrue(world.needsReplan(12,at,List.of(new RouteStep(new Vector(260.5,245.5,97.75),Affordance.JUMP)),true));var first=world.corridor(at,new Vector(260.5,245.5,97.75),Set.of());world.beginPlanning(new Observer(1,1),0);first.advance();assertFalse(first.deferred());world.endPlanning(false);var second=world.corridor(at,new Vector(260.5,245.5,97.75),Set.of());world.beginPlanning(new Observer(2,1),0);second.advance();assertTrue(second.deferred());assertFalse(second.done());world.endPlanning(false);world.beginPlanning(new Observer(2,1),1);second.advance();assertFalse(second.deferred());world.endPlanning(false);}
    @Test void retainedBidirectionalSearchBoundsEverySliceAndRejectsStaleExcludedChains(){for(var value:list(FIXTURE.get("corridors"))){var c=map(value);var search=new SurfaceCorridorSearch(Base64.getDecoder().decode(string(c.get("supports"))),integer(c.get("width")),integer(c.get("height")),integer(c.get("start")),integer(c.get("target")),Set.of(),null,0,0,null);var slices=new ArrayList<Integer>();int previous=0;while(!search.done()){search.advance();assertTrue(search.expansions()-previous<=512);previous=search.expansions();slices.add(previous);if(slices.size()==1&&c.get("late_edge")!=null){var edge=list(c.get("late_edge"));search.exclude(new Edge(cell(edge.get(0)),cell(edge.get(1))));}assertTrue(slices.size()<=65);}equal(c.get("slices"),slices);equal(c.get("path"),search.path());}}

}
